    `stages: ${state.stages.join(" \u2192 ")}`,
    `risks: ${state.risks.join(", ") || "(none)"}`,
    `adversarialDesign: ${state.adversarialDesign}`,
    `adversarialCode: ${state.adversarialCode}`
